e:90px 130px;animation:rainFall .65s linear infinite;transition:opacity 1s}body.sunny .sun{opacity:.95}body.cloudy .cloud,body.rainy .cloud{opacity:.76}body.rainy .cloud{filter:brightness(.62)}body.rainy .rain{opacity:.8}body.cloudy .weather-tint{background:rgba(44,62,81,.28)}body.rainy .weather-tint{background:rgba(8,20,37,.48)}body.night .weather-tint{background:rgba(2,8,28,.64)}body.night .cloud{opacity:.18}body.night .sun{opacity:0}@keyframes cloudMove{from{left:-260px}to{left:calc(100vw + 260px)}}@keyframes rainFall{to{background-position:-25px 130px}}@keyframes floatSun{50%{transform:translateY(10px)}}.app{position:relative;z-index:3;max-width:1120px;margin:auto}.top{display:flex;justify-content:space-between;align-items:center;gap:15px;flex-wrap:wrap;margin-bottom:34px}.brand{display:flex;align-items:center;gap:12px}.brand-icon{font-size:42px;filter:drop-shadow(0 4px 12px #28caff70)}.brand-name{font-weight:900;font-size:clamp(23px,4vw,34px);letter-spacing:.5px}.brand-name span{color:#24caff}.tagline{font-size:13px;color:#e0f2ff;margin-top:2px}.country{padding:10px 15px;border:1px solid #b9e5ff88;border-radius:24px;background:#04284c8a;font-size:13px}.intro{margin-bottom:24px}.intro h1{font-size:clamp(30px,5vw,45px);margin:0 0 10px;text-shadow:0 2px 14px #00213e80}.intro p{color:#eff8ff;line-height:1.55;max-width:510px;margin:0}.glass{background:var(--glass);border:1px solid var(--line);border-radius:22px;box-shadow:0 14px 35px #00152d35;backdrop-filter:blur(15px);-webkit-backdrop-filter:blur(15px)}.searchrow{display:flex;gap:10px;align-items:center;margin-bottom:20px;padding:10px;border-radius:35px}.searchrow input{flex:1;min-width:0;background:transparent;color:#fff;border:0;outline:none;padding:8px 12px}.searchrow input::placeholder{color:#d5e8f8}.btn{border:1px solid #9ddcff88;background:linear-gradient(135deg,#0799ff,#0871df);color:white;font-weight:700;border-radius:24px;padding:12px 19px;transition:.2s}.btn:hover,.city:hover{transform:translateY(-2px);f