032343c9;border:1px solid #70cfff68;border-radius:15px}.hour-time{font-size:12px;color:#e1f1ff}.hour-icon{font-size:27px;margin:13px 0}.hour-temp{font-size:21px;font-weight:800}.hour-rain{font-size:12px;color:#bceaff;margin-top:9px}.status{display:none;padding:12px 15px;margin:0 0 16px;border:1px solid #8bd9ff80;border-radius:12px;background:#04284bd9;line-height:1.5;font-size:13px}.footer{text-align:center;color:#e0efff;font-size:12px;line-height:1.8;padding:12px 0 22px}.footer a{color:#66e5ff}.credit{opacity:.9}@media(max-width:720px){body{padding:15px}.top{margin-bottom:24px}.brand-icon{font-size:34px}.searchrow{flex-wrap:wrap;border-radius:18px}.searchrow input{flex-basis:100%;padding:12px}.gps{width:100%}.hero{min-height:310px;background-position:60% center}.hero-content{padding:24px 20px}.metrics{grid-template-columns:repeat(2,1fr)}.metric{padding:15px 12px}.metric-value{font-size:20px}.hours{grid-template-columns:repeat(6,90px)}.country{font-size:12px}}@media(prefers-reduced-motion:reduce){*,*:before,*:after{animation:none!important;transition:none!important}}

/* ===== REALISMO METEOROLÓGICO: SOL, NUBES Y LLUVIA ===== */
.scenery {
  background-size: cover;
  background-position: center center;
  transform: scale(1.015);
  will-change: transform, filter;
  transition: filter 2s ease, background-position 2s ease;
}
.weather-tint {
  backdrop-filter: saturate(1.08);
  -webkit-backdrop-filter: saturate(1.08);
  transition: background 2s ease;
}
.sun {
  width: clamp(88px, 12vw, 145px);
  height: clamp(88px, 12vw, 145px);
  background: radial-gradient(circle at 38% 34%, #fffde8 0%, #fff6ad 16%, #ffe66b 34%, #ffc13b 57%, #ff9c24 73%, #ff8b1b00 76%);
  box-shadow: 0 0 18px 8px #fff0a855, 0 0 52px 24px #ffcf5b80, 0 0 115px 48px #ffb33d55;
  filter: saturate(1.12);
  animation: sunDrift 9s ease-in-out infinite, sunPulse 5s ease-in-out infinite;
}
.sun::before {
  content: "";
  position: absolute;
  inset: -42%;
  border-radius: 50%;
  background: repeating-conic-gradient(from 0deg, #ffeaa533 0deg 7deg, transparent 7deg 18deg);
  -webkit-mask: radial-gradient(circle, transparent 0 48%, #000 54% 64%, transparent 72%);
  mask: radial-gradient(circle, transparent 0 48%, #000 54% 64%, transparent 72%);
  animation: sunRays 100s linear infinite;
}
.sun::after {
  content: "";
  position: absolute;
  inset: -90%;
  border-radius: 50%;
  background: radial-gradient(circle, #ffdf7b24 0 28%, #ffce4a15 42%, transparent 69%);
  filter: blur(12px);
}
.cloud {
  width: clamp(210px, 29vw, 340px);
  height: 75px;
  border-radius: 80px;
  background:
    radial-gradient(ellipse at 22% 72%, #ffffff 0%, #eef7ff 28%, transparent 53%),
    radial-gradient(ellipse at 43% 37%, #f8fcff 0%, #dceaf5 38%, transparent 61%),
    radial-gradient(ellipse at 69% 66%, #d6e4f0 0%, #a9c2d8 45%, transparent 68%),
    linear-gradient(180deg, #f4faff 0%, #d3e2ee 50%, #8ea9c1 100%);
  background-blend-mode: screen, screen, normal, normal;
  filter: drop-shadow(0 14px 17px #00152d30);
  box-shadow: inset 0 8px 16px #ffffffa0, inset 0 -10px 16px #6585a255;
  animation: cloudFloat 8s ease-in-out infinite, cloudMove 48s linear infinite;
  will-change: left, transform;
}
.cloud::before {
  width: 120px;
  height: 120px;
  left: 30px;
  top: -62px;
  background: radial-gradient(circle at 36% 32%, #fff 0%, #f0f7fc 38%, #c2d7e7 72%, #92adc3 100%);
  box-shadow: inset -8px -9px 14px #6e8ca633, inset 7px 5px 14px #fff9;
}
.cloud::after {
  width: 145px;
  height: 135px;
  right: 25px;
  top: -76px;
  background: radial-gradient(circle at 35% 28%, #fff 0%, #f4f9fd 32%, #ccdeec 67%, #91abc2 100%);
  box-shadow: inset -10px -10px 18px #6786a633, inset 7px 5px 14px #fff9;
}
.cloud.c2 { animation-duration: 58s, 58s; }
.cloud.c3 { animation-duration: 52s, 52s; }
body.sunny .sun { opacity: 1; }
body.sunny .scenery { filter: saturate(1.1) brightness(1.03); }
body.sunny .weather-tint { background: linear-gradient(180deg, #1977b00a, #ffd28b0a 55%, #05234220); }
body.sunny .cloud { opacity: .20; }
body.cloudy .scenery { filter: saturate(.78) brightness(.84); }
body.cloudy .sun { opacity: .18; box-shadow: 0 0 50px 22px #e5f2ff30; }
body.cloudy .cloud {
  opacity: .9;
  filter: drop-shadow(0 16px 19px #00172b55) brightness(.86);
}
body.cloudy .weather-tint { background: linear-gradient(180deg, #52677a38, #435b7044 55%, #07192b66); }
body.rainy .scenery { filter: saturate(.62) brightness(.62) contrast(1.08); }
body.rainy .sun { opacity: 0; }
body.rainy .cloud {
  opacity: .98;
  filter: brightness(.55) saturate(.72) drop-shadow(0 17px 20px #0008);
}
body.rainy .weather-tint { background: linear-gradient(180deg, #111d2c65, #1b3046a3 60%, #061426b8); }
.rain {
  background-image:
    repeating-linear-gradient(101deg, transparent 0 17px, #d9f1ff70 18px 19px, transparent 20px 39px),
    repeating-linear-gradient(104deg, transparent 0 57px, #e6f6ff45 58px 60px, transparent 61px 94px);
  background-size: 78px 125px, 135px 175px;
  filter: drop-shadow(0 0 2px #b7e8ff30);
  animation: rainFall .48s linear infinite;
}
.rain::before, .rain::after {
  content: "";
  position: absolute;
  inset: 0;
  pointer-events: none;
}
.rain::before {
  background: repeating-linear-gradient(102deg, transparent 0 88px, #d8f0ff35 89px 91px, transparent 92px 145px);
  background-size: 170px 210px;
  animation: rainFall .8s linear infinite;
}
.rain::after {
  background: linear-gradient(180deg, transparent 0%, #a8cce51c 70%, #d6efff24 100%);
  backdrop-filter: blur(.25px);
}
body.rainy .rain { opacity: .78; }
body.night .scenery { filter: brightness(.42) saturate(.72) hue-rotate(8deg); }
body.night .weather-tint { background: linear-gradient(180deg, #02071888, #07152b80 55%, #020713aa); }
body.night .sun { opacity: 0; }
body.night .cloud { opacity: .24; filter: brightness(.36) saturate(.6); }
body.night.rainy .rain { opacity: .6; }
@keyframes sunDrift { 0%,100% { transform: translateY(0) scale(1); } 50% { transform: translateY(8px) scale(1.025); } }
@keyframes sunPulse { 0%,100% { filter: saturate(1); } 50% { filter: saturate(1.2) brightness(1.04); } }
@keyframes sunRays { to { transform: rotate(360deg); } }
@keyframes cloudFloat { 0%,100% { margin-top: 0; } 50% { margin-top: 9px; } }
@media (max-width: 700px) {
  .sun { top: 14%; right: 7%; }
  .cloud { transform: scale(.78); }
}
@media (prefers-reduced-motion: reduce) {
  .sun, .sun::before, .cloud, .rain, .rain::before { animation: none !important; }
}



/* ===== ACABADO VISUAL REFINADO: CIELO CINEMATOGRÁFICO ===== */
.scenery {
  transform: none !important;
  background-position: center center !important;
  background-size: cover !important;
  will-change: filter;
}
.weather-tint {
  backdrop-filter: none !important;
  -webkit-backdrop-filter: none !important;
}
/* Sol con halo atmosférico suave, sin aspecto de icono */
.sun {
  width: clamp(76px, 9vw, 118px) !important;
  height: clamp(76px, 9vw, 118px) !important;
  border-radius: 50%;
  background: radial-gradient(circle at 38% 34%, #fffef1 0%, #fff7c5 17%, #ffe88a 38%, #ffd05b 57%, #ffbd4a 68%, #ffbd4a00 73%) !important;
  box-shadow: 0 0 24px 8px #fff1b34d, 0 0 70px 28px #ffd06b45, 0 0 150px 65px #ffbf5130 !important;
  filter: blur(.2px) !important;
}
.sun::before {
  inset: -65% !important;
  background: radial-gradient(circle, #ffdf8a22 0 30%, #ffcf6320 40%, transparent 68%) !important;
  -webkit-mask: none !important;
  mask: none !important;
  filter: blur(12px);
  animation: none !important;
}
.sun::after { display: none !important; }
/* Nubes con volumen atmosférico y bordes difuminados, no geométricos */
.cloud {
  width: clamp(240px, 32vw, 420px) !important;
  height: 100px !important;
  border-radius: 50% 48% 42% 45% !important;
  background:
    radial-gradient(ellipse at 18% 69%, rgba(255,255,255,.97) 0 13%, rgba(240,248,255,.88) 28%, transparent 52%),
    radial-gradient(ellipse at 39% 39%, rgba(255,255,255,.98) 0 17%, rgba(232,243,251,.9) 35%, transparent 57%),
    radial-gradient(ellipse at 62% 31%, rgba(250,253,255,.92) 0 15%, rgba(209,226,239,.85) 34%, transparent 57%),
    radial-gradient(ellipse at 82% 68%, rgba(198,218,233,.94) 0 12%, rgba(154,181,202,.74) 34%, transparent 58%) !important;
  box-shadow: none !important;
  filter: blur(1.5px) drop-shadow(0 14px 22px rgba(0,17,37,.13)) !important;
  animation: cloudMove 58s linear infinite, cloudFloat 12s ease-in-out infinite !important;
  will-change: left, transform;
}
.cloud::before {
  width: 60% !important;
  height: 100% !important;
  left: 4% !important;
  top: -24% !important;
  background: radial-gradient(ellipse at 50% 65%, rgba(255,255,255,.85), rgba(234,244,251,.58) 48%, transparent 74%) !important;
  box-shadow: none !important;
  filter: blur(5px);
}
.cloud::after {
  width: 62% !important;
  height: 110% !important;
  right: 3% !important;
  top: -37% !important;
  background: radial-gradient(ellipse at 45% 65%, rgba(242,249,255,.85), rgba(198,218,233,.62) 47%, transparent 75%) !important;
  box-shadow: none !important;
  filter: blur(6px);
}
.cloud.c1 { top: 17% !important; }
.cloud.c2 { top: 35% !important; opacity: 0; animation-duration: 72s, 14s !important; }
.cloud.c3 { top: 57% !important; opacity: 0; animation-duration: 64s, 16s !important; }
body.sunny .cloud { opacity: .12 !important; }
body.cloudy .cloud { opacity: .78 !important; }
body.rainy .cloud {
  opacity: .94 !important;
  filter: brightness(.56) saturate(.68) blur(2px) drop-shadow(0 16px 25px rgba(0,0,0,.25)) !important;
}
body.night .cloud { opacity: .16 !important; filter: brightness(.38) saturate(.65) blur(2px) !important; }
/* Lluvia diagonal de varias profundidades, más fina y menos saturada */
.rain {
  background-image:
    repeating-linear-gradient(108deg, transparent 0 25px, rgba(222,242,255,.44) 26px, transparent 27px 53px),
    repeating-linear-gradient(106deg, transparent 0 74px, rgba(219,239,255,.26) 75px 76px, transparent 77px 125px) !important;
  background-size: 100px 155px, 170px 220px !important;
  filter: blur(.15px) !important;
  animation: rainFall .72s linear infinite !important;
}
.rain::before {
  background: repeating-linear-gradient(106deg, transparent 0 110px, rgba(240,249,255,.2) 111px 112px, transparent 113px 175px) !important;
  background-size: 210px 250px !important;
  animation: rainFall 1.05s linear infinite !important;
}
body.rainy .rain { opacity: .55 !important; }
body.night.rainy .rain { opacity: .4 !important; }
/* Interfaz más limpia y legible sobre la fotografía */
.glass, .hero {
  border-color: rgba(170,220,255,.42) !important;
  box-shadow: 0 18px 48px rgba(0,12,30,.24), inset 0 1px 0 rgba(255,255,255,.08) !important;
}
.hero {
  background-position: center 58% !important;
  border-width: 1px !important;
}
.metric-icon { color: #aeeaff; }
.city { backdrop-filter: blur(8px); }
.city.active { box-shadow: 0 0 0 1px rgba(255,255,255,.18), 0 5px 18px rgba(0,126,255,.25); }
@media (max-width: 700px) {
  .cloud { width: 260px !important; height: 78px !important; }
  .sun { top: 12% !important; right: 8% !important; }
  .hero { background-position: 62% center !important; }
}

